@startuml

class Airline {
  + Name : string
}

class Employee {
  + Name : string
  + StartDate : date
}

class BoeingSalesperson {
  + SalesId : int
}

class AircraftModel {
  + ModelName : string
  + Description : string
}

class Contract {
  + ContractNumber : int
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + AcquisitionId : int
  + Model : AircraftModel
  + Price : double
  + Options : string[]
  + Customizations : string[]
  + DeliveryDate : date
}

class SalesAgreement {
  + AgreementNumber : int
  + Contract : Contract
  + Acquisitions : Acquisition[]
}

Airline "0..1" -- "0..*" Employee
Airline "0..1" o-- "0..*" BoeingSalesperson
BoeingSalesperson "0..*" -- "0..*" SalesAgreement
SalesAgreement "1" -- "1" Contract
Contract "1" -- "*" Acquisition

@enduml

